func newPayProfileComponent() unsafe.Pointer {
	return unsafe.Pointer(new(driverpay.PayProfileComponent))
}

func newNPayProfileComponent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]driverpay.PayProfileComponent, n)))
}

func ptrPayProfileComponent(p unsafe.Pointer, c int32) any {
	r := (*driverpay.PayProfileComponent)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.PayProfileID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 5:
		return (*string)(unsafe.Pointer(&r.Method))
	case 6:
		return &r.Description
	case 7:
		return &r.Rate
	case 8:
		return (*string)(unsafe.Pointer(&r.RevenueBasis))
	case 9:
		return &r.Bands
	case 10:
		return (*int64)(unsafe.Pointer(&r.FreeTimeMinutes))
	case 11:
		return &r.MinAmountMinor
	case 12:
		return &r.MaxAmountMinor
	case 13:
		return (*int64)(unsafe.Pointer(&r.Sequence))
	case 14:
		return &r.IsActive
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valuePayProfileComponent(p unsafe.Pointer, c int32) any {
	r := (*driverpay.PayProfileComponent)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.PayProfileID)
	case 4:
		return string(r.Kind)
	case 5:
		return string(r.Method)
	case 6:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 7:
		return r.Rate
	case 8:
		if r.RevenueBasis == "" {
			return nil
		}
		return string(r.RevenueBasis)
	case 9:
		if r.Bands == nil {
			return nil
		}
		return r.Bands
	case 10:
		return int64(r.FreeTimeMinutes)
	case 11:
		if r.MinAmountMinor == nil {
			return nil
		}
		return *r.MinAmountMinor
	case 12:
		if r.MaxAmountMinor == nil {
			return nil
		}
		return *r.MaxAmountMinor
	case 13:
		return int64(r.Sequence)
	case 14:
		return r.IsActive
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

